        margin: -1px;
        overflow: hidden;
        clip: rect(0 0 0 0);
        clip-path: inset(50%);
        white-space: nowrap;
      }

      .radio-option label {
        display: flex;
        align-items: center;
        gap: 0.85rem;
        min-height: 3.5rem;
        padding: 1rem;
        color: var(--text);
        background: rgba(15, 23, 42, 0.9);
        border: 1px solid var(--border);
        border-radius: 1rem;
        cursor: pointer;
        transition:
          border-color 150ms ease,
          background 150ms ease,
          transform 150ms ease;
      }

      .radio-option label::before {
        content: "";
