        width: 1.25rem;
        height: 1.25rem;
        border: 2px solid #94a3b8;
        border-radius: 50%;
        background: #020617;
        box-shadow: inset 0 0 0 0.28rem #020617;
      }

      .radio-option input:checked + label {
        border-color: var(--accent);
        background: linear-gradient(135deg, rgba(14, 116, 144, 0.45), var(--panel-strong));
      }

      .radio-option input:checked + label::before {
        background: var(--accent);
        border-color: var(--accent);
      }

      .radio-option input:focus-visible + label {
        outline: 3px solid var(--accent);
        outline-offset: 4px;
      }

      .radio-option label:hover {
        border-color: #bae6fd;
