    <a class="skip-link" href="#main">Skip to main content</a>
    <main id="main">
      <section class="card" aria-labelledby="page-title">
        <h1 id="page-title">Notification preferences</h1>
        <p class="intro">Choose how you would like to hear about important updates.</p>
        <p class="required-note"><span aria-hidden="true">*</span> indicates a required question.</p>

        <form id="notification-form" novalidate>
          <div class="form-field">
