              <legend>
                How do you prefer to receive notifications?
                <span aria-hidden="true">*</span>
              </legend>
              <p class="field-help" id="notification-help">Select one notification method.</p>
              <p class="field-help status error" id="notification-error" hidden>Error: Choose a notification method.</p>

              <div class="radio-list">
                <div class="radio-option">
                  <input id="notification-email" type="radio" name="notificationPreference" value="Email" required>
                  <label for="notification-email">Email</label>
                </div>
                <div class="radio-option">
                  <input id="notification-sms" type="radio" name="notificationPreference" value="SMS" required>
                  <label for="notification-sms">SMS</label>
                </div>
                <div class="radio-option">
                  <input id="notification-push" type="radio" name="notificationPreference" value="Push Notifications" required>
                  <label for="notification-push">Push Notifications</label>
                </div>
              </div>
            </fieldset>
          </div>

          <button type="submit">Save notification preference</button>
          <p class="status" id="form-status" role="status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#notification-form");
      const statusMessage = document.querySelector("#form-status");
      const errorMessage = document.querySelector("#notification-error");
      const notificationRadios = [...document.querySelectorAll('input[name="notificationPreference"]')];

      function setInvalidState(isInvalid) {
        errorMessage.hidden = !isInvalid;
        notificationRadios.forEach((radio) => {
          radio.setAttribute("aria-invalid", String(isInvalid));
        });
      }

      notificationRadios.forEach((radio) => {
        radio.addEventListener("change", () => {
          setInvalidState(false);
          statusMessage.textContent = "";
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const selected = notificationRadios.find((radio) => radio.checked);

        if (!selected) {
          setInvalidState(true);
          statusMessage.textContent = "";
          notificationRadios[0].focus();
          return;
        }

        setInvalidState(false);
        statusMessage.textContent = `Preference saved: ${selected.value}.`;
      });
    </script>
